<?php get_header(); while(have_posts()):the_post(); ?><article <?php post_class('glass content-panel single-article'); ?>><div class="eyebrow"><?php echo esc_html(get_the_date()); ?></div><h1><?php the_title(); ?></h1><?php if(has_post_thumbnail()) the_post_thumbnail('large', ['class'=>'post-cover']); ?><div class="entry-content"><?php the_content(); ?></div><div class="post-links"><?php the_post_navigation(); ?></div></article><?php if(get_post_type()==='post') { if(has_action('cancha_ads_news_feed'))do_action('cancha_ads_news_feed');comments_template(); } ?><?php endwhile; get_footer(); ?>
